const run = $('Set Run Context').first().json;
const allItems = $input.all();
const cutoff = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString();
const newItems = allItems.filter(i => i.json.status === 'new' && i.json.date_found >= cutoff);
if (newItems.length === 0) return [{ json: { status: 'no_new_evidence', run_id: run.run_id } }];
return newItems.map(i => ({ json: { ...i.json, run_id: run.run_id, week: run.week } }));

// Stage 3 Section 1: Tiered capability map
// Restructures flat rows into per-lane tier buckets.
// unclear is kept as its own bucket (not merged into partial)
// to support explicit unclear handling in Build Analysis Prompts.
const items = $input.all();
const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
const capMap = {};

for (const item of items) {
  const r = item.json;
  if (!r.capability_area || !r.feature_name) continue;
  if (r.last_checked && r.last_checked < thirtyDaysAgo) continue;
  const confidence = Number(r.confidence) || 0;
  if (confidence < 3) continue;

  const lane = r.capability_area;
  if (!capMap[lane]) {
    capMap[lane] = {
      production_mature: [],
      documented: [],
      partial: [],
      unclear: [],
      sample_only: [],
      no_evidence: false,
      source_types_present: []
    };
  }

  const entry = {
    feature_name:     r.feature_name,
    capability_tag:   r.capability_tag || '',
    product_name:     r.product_name,
    support_maturity: r.support_maturity,
    maturity_reason:  r.maturity_reason || '',
    source_weight:    r.source_weight || 'low',
    source_type:      r.source_type || '',
    observed_fact:    r.observed_fact || '',
    confidence:       confidence
  };

  const maturity = r.support_maturity || '';
  if (maturity === 'production_mature') {
    capMap[lane].production_mature.push(entry);
  } else if (maturity === 'documented') {
    capMap[lane].documented.push(entry);
  } else if (maturity === 'partial') {
    capMap[lane].partial.push(entry);
  } else if (maturity === 'unclear') {
    capMap[lane].unclear.push(entry);
  } else if (maturity === 'sample_only') {
    capMap[lane].sample_only.push(entry);
  } else {
    // Unknown maturity values fall into unclear
    capMap[lane].unclear.push(entry);
  }

  if (r.source_type && !capMap[lane].source_types_present.includes(r.source_type)) {
    capMap[lane].source_types_present.push(r.source_type);
  }
}

// Set no_evidence flag: true only when all 5 tiers are empty
for (const lane of Object.keys(capMap)) {
  const l = capMap[lane];
  l.no_evidence = (
    l.production_mature.length === 0 &&
    l.documented.length === 0 &&
    l.partial.length === 0 &&
    l.unclear.length === 0 &&
    l.sample_only.length === 0
  );
}

return [{ json: { ping_capability_map: capMap, icm_loaded: Object.keys(capMap).length > 0, areas_covered: Object.keys(capMap) } }];

const ev = $('Build Analysis Prompts').item.json;
const apiResponse = $input.first().json;

let ai = {};
try {
  const text = apiResponse.content?.[0]?.text || '{}';
  const m = text.match(/\{[\s\S]*\}/);
  if (m) ai = JSON.parse(m[0]);
} catch(e) {}

const now = new Date().toISOString();
return [{ json: {
  finding_id: `SF-${ev.competitor_id}-${ev.ev_id || Date.now()}`,
  week: ev.week, run_id: ev.run_id, competitor_id: ev.competitor_id,
  lane: ev.lane || '',
  source_url: ev.source_url || '',
  source_type: ev.source_type || '',
  evidence_count: 1,
  ev_ids: [ev.ev_id].filter(Boolean),
  what_changed: JSON.stringify(ai.what_changed || []),
  likely_direction: ai.likely_direction || '',
  product_area_tags: JSON.stringify(ai.product_area_tags || []),
  relevance_score: ai.relevance_score || 2, confidence_score: ai.confidence_score || 2,
  observed_facts: ai.observed_facts || '', analyst_interpretation: ai.analyst_interpretation || '',
  gap_vs_ping: ai.gap_vs_ping || 'insufficient evidence',
  parity_vs_ping: ai.parity_vs_ping || 'insufficient evidence',
  ping_advantage: ai.ping_advantage || 'insufficient evidence',
  recommended_action: ai.recommended_action || 'Watch',
  review_flag: ai.review_flag ? 'TRUE' : 'FALSE',
  review_flag_reason: ai.review_flag_reason || '',
  status: 'draft', created_at: now
} }];

const item = $input.first().json;
const evIds = item.ev_ids || [];
if (evIds.length === 0) return [{ json: { ev_id: null, status: 'processed' } }];
return evIds.map(ev_id => ({ json: { ev_id, status: 'processed' } }));

